// rdmaFleetFixture describes one testdata/rdmasysfs/fleet file. The rows are
// generated by fleet-export.py from a fleet rescan; see
// rdma_counters_fleet_generated_linux_test.go.
type rdmaFleetFixture struct {
	file, category, description, expected string
	// rate is the port rate in bytes per second, parsed by the exporter.
	rate uint64
	// minBytesPerPacket and maxBytesPerPacket bound the transmitted bytes per
	// packet between the two samples; 0 is no bound.
	minBytesPerPacket, maxBytesPerPacket float64
	uncataloged                          []string
	// unreadable files failed to read on the fleet; the test answers EINVAL.
	unreadable []string
	// saturated files hold a fixed-width register's maximum.
	saturated []string
}

const rdmaFleetDir = "fleet"

func rdmaSaturated(value string) bool {
	return value == strconv.FormatUint(1<<16-1, 10) || value == strconv.FormatUint(1<<32-1, 10) || value == strconv.FormatUint(^uint64(0), 10)
}

// rdmaFleetReads counts the collector's file reads: a file holding
// READ_ERROR fails with fail, as the fleet port did.
type rdmaFleetReads struct {
	files *fakeRDMAFiles
	count map[string]int
}

func installFleetReads(t testing.TB, c *rdmaOptionalCollector, fail error) *rdmaFleetReads {
	t.Helper()
	files := newFakeRDMAFiles()
	files.fail = fail
	useRDMAFiles(t, c, files)
	return &rdmaFleetReads{files: files, count: files.reads}
}

func TestRDMAFleetFixturesComplete(t *testing.T) {
	entries, err := os.ReadDir(filepath.Join("testdata", "rdmasysfs", rdmaFleetDir))
	if err != nil {
		t.Fatal(err)
	}
	files, rows := make([]string, 0, len(entries)), make([]string, 0, len(rdmaFleetFixtures))
	for _, entry := range entries {
		files = append(files, entry.Name())
	}
	for _, row := range rdmaFleetFixtures {
		rows = append(rows, row.file)
	}
	slices.Sort(rows)
	t.Logf("positive: every fleet fixture has exactly one generated row; expected: %d files, %d rows, equal", len(files), len(rows))
	if !slices.Equal(files, rows) {
		t.Fatalf("fixtures %v, rows %v; rerun fleet-export.py", files, rows)
	}
}

// TestRDMACountersFleetSysfs collects every fleet fixture through the real
// collector: each file shape seen on the fleet must be supported, keep every
// cataloged readable counter, and survive a second sample with the schema the
// first one returned.
func TestRDMACountersFleetSysfs(t *testing.T) {
	for _, tc := range rdmaFleetFixtures {
		t.Run(strings.TrimSuffix(tc.file, ".txt"), func(t *testing.T) {
			t.Logf("%s: %s; expected: %s", tc.category, tc.description, tc.expected)
			snapshot := loadRDMASysfsSnapshot(t, filepath.Join(rdmaFleetDir, tc.file))
			if got := snapshot.matching(func(v string) bool { return v == rdmaReadError }); !slices.Equal(got, tc.unreadable) {
				t.Fatalf("fixture unreadable %v, row %v", got, tc.unreadable)
			}
			if got := snapshot.matching(rdmaSaturated); !slices.Equal(got, tc.saturated) {
				t.Fatalf("fixture saturated %v, row %v", got, tc.saturated)
			}
			c, job, port := snapshotRDMAFixture(t, snapshot)
			reads := installFleetReads(t, c, syscall.EINVAL)
			first := c.Collect(t.Context(), job)
			if first.Support != model.Supported || first.Err != nil || first.StatisticSchema == nil {
				t.Fatalf("%s: support %v err %v schema %v", tc.expected, first.Support, first.Err, first.StatisticSchema)
			}
			checkRealSysfsSamples(t, tc.expected, port, first.Samples, tc.uncataloged, tc.unreadable, tc.rate, nil, false)
			for _, name := range first.StatisticSchema.Names {
				if slices.Contains(tc.unreadable, name) {
					t.Fatalf("%s: returned schema still names unreadable %s", tc.expected, name)
				}
			}
			for _, s := range first.Samples {
				if strings.HasPrefix(s.Descriptor, "go_link_monitor_infiniband_port_transmit_wait") && slices.Contains(tc.saturated, "counters/port_xmit_wait") {
					if got, _ := s.Number.Uint64(); got != 1<<32-1 {
						t.Fatalf("%s: saturated port_xmit_wait reported %d", tc.expected, got)
					}
				}
			}

			// Second sample: the t1 values, collected with the first schema,
			// as the reducer does on the next poll.
			for path, value := range snapshot.later {
				rdmaWrite(t, filepath.Join(filepath.Dir(filepath.Dir(port)), path), value+"\n")
			}
			clear(reads.count)
			job.StatisticSchema = first.StatisticSchema
			second := c.Collect(t.Context(), job)
			if second.Support != model.Supported || second.Err != nil {
				t.Fatalf("%s: second sample support %v err %v", tc.expected, second.Support, second.Err)
			}
			checkRealSysfsSamples(t, tc.expected, port, second.Samples, tc.uncataloged, tc.unreadable, tc.rate, nil, false)
			for _, name := range tc.unreadable {
				if n := reads.count[name]; n != 0 {
					t.Fatalf("%s: unreadable %s read %d times on the second sample", tc.expected, name, n)
				}
			}
			checkFleetTraffic(t, tc, snapshot, first.Samples, second.Samples)
		})
	}
}

// checkFleetTraffic compares the two samples: counters never go backwards, the
// data counters stay under the port rate, and the bytes per transmitted packet
// fall inside the row's bounds, which pins the four-octet data scale.
func checkFleetTraffic(t *testing.T, tc rdmaFleetFixture, snapshot rdmaSysfsSnapshot, first, second []model.Sample) {
	t.Helper()
	before := map[string]uint64{}
	for _, s := range first {
		if s.Kind == model.SampleCounter {
			before[s.Descriptor], _ = s.Number.Uint64()
		}
	}
	deltas := map[string]uint64{}
	for _, s := range second {
		was, ok := before[s.Descriptor]
		if !ok {
			continue
		}
		now, _ := s.Number.Uint64()
		if now < was {
			t.Fatalf("%s: %s went from %d to %d", tc.expected, s.Descriptor, was, now)
		}
		deltas[s.Descriptor] = now - was
	}
	if len(snapshot.later) == 0 {
		if moved := slices.Collect(maps.Keys(deltas)); slices.ContainsFunc(moved, func(d string) bool { return deltas[d] != 0 }) {
			t.Fatalf("%s: counters moved without t1 values: %v", tc.expected, deltas)
		}
		return
	}
	elapsed, err := strconv.ParseFloat(snapshot.header["elapsed"], 64)
	if err != nil || elapsed <= 0 {
		t.Fatalf("fixture elapsed %q: %v", snapshot.header["elapsed"], err)
	}
	for _, metric := range []string{"port_data_transmitted_bytes_total", "port_data_received_bytes_total"} {
		if d := deltas["go_link_monitor_infiniband_"+metric]; float64(d) > float64(tc.rate)*elapsed {
			t.Fatalf("%s: %s moved %d bytes in %.3fs, over the %d B/s rate", tc.expected, metric, d, elapsed, tc.rate)
		}
	}
	if tc.minBytesPerPacket == 0 && tc.maxBytesPerPacket == 0 {
		return
	}
	packets := deltas["go_link_monitor_infiniband_port_packets_transmitted_total"]
	if packets == 0 {
		t.Fatalf("%s: bounded row without transmitted packets", tc.expected)
	}
	perPacket := float64(deltas["go_link_monitor_infiniband_port_data_transmitted_bytes_total"]) / float64(packets)
	t.Logf("%.0f bytes per transmitted packet over %d packets", perPacket, packets)
	if perPacket < tc.minBytesPerPacket || (tc.maxBytesPerPacket != 0 && perPacket > tc.maxBytesPerPacket) {
		t.Fatalf("%s: %.0f bytes per packet, want [%v, %v]", tc.expected, perPacket, tc.minBytesPerPacket, tc.maxBytesPerPacket)
	}
}

// TestRDMACountersFleetReadErrors replays the fleet's unreadable ConnectX-7
// InfiniBand port (mlx5 answers EINVAL for 13 PortCounters files) with the
// errors a counter read can return.
func TestRDMACountersFleetReadErrors(t *testing.T) {
	var fixture rdmaFleetFixture
	for _, row := range rdmaFleetFixtures {
		if len(row.unreadable) != 0 {
			fixture = row
			break
		}
	}
	if fixture.file == "" {
		t.Fatal("no fleet fixture has unreadable counters")
	}
	for _, tc := range []struct {
		name, category, description, expected string
		fail                                  error
		// all makes every counter file unreadable, not just the fleet's.
		all bool
		// heal makes the files readable again before the second sample.
		heal    bool
		support model.Support
	}{
		{name: "einval", category: "positive", description: "the fleet port: EINVAL for the 13 PortCounters files",
			expected: "supported; the 13 files are skipped and pruned, and the second sample does not read them", fail: syscall.EINVAL, support: model.Supported},
		{name: "eopnotsupp", category: "positive", description: "the same files answer EOPNOTSUPP",
			expected: "skipped like EINVAL, not the whole collector unsupported", fail: syscall.EOPNOTSUPP, support: model.Supported},
		{name: "eio", category: "negative", description: "the same files answer EIO",
			expected: "the whole set fails and the schema is invalidated: EIO is not a per-file gap", fail: syscall.EIO, support: model.SupportUnknown},
		{name: "enoent", category: "negative", description: "a listed file vanished between listing and reading",
			expected: "the whole set fails: the counter set changed", fail: fs.ErrNotExist, support: model.SupportUnknown},
		{name: "eacces", category: "negative", description: "the files are not readable by the monitor",
			expected: "the whole set fails rather than silently dropping counters", fail: syscall.EACCES, support: model.SupportUnknown},
		{name: "all", category: "corner", description: "every counter file on the port answers EINVAL, catch-all files included",
			expected: "supported with the rate sample only, and an empty pruned schema", fail: syscall.EINVAL, all: true, support: model.Supported},
		{name: "heal", category: "boundary", description: "the files read again after the first sample pruned them",
			expected: "still skipped until the schema is rebuilt: each unreadable file costs one read per schema", fail: syscall.EINVAL, heal: true, support: model.Supported},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Logf("%s: %s; expected: %s", tc.category, tc.description, tc.expected)
			snapshot := loadRDMASysfsSnapshot(t, filepath.Join(rdmaFleetDir, fixture.file))
			c, job, port := snapshotRDMAFixture(t, snapshot)
			unreadable := fixture.unreadable
			if tc.all {
				unreadable = nil
				for _, name := range snapshot.counterFiles() {
					rdmaWrite(t, filepath.Join(port, name), rdmaReadError+"\n")
					unreadable = append(unreadable, name)
				}
			}
			reads := installFleetReads(t, c, tc.fail)
			full, err := c.counterSchema(t.Context(), job.RDMA.Ports)
			if err != nil {
				t.Fatal(err)
			}
			names := slices.Clone(full.Names)
			job.StatisticSchema = full
			first := c.Collect(t.Context(), job)
			if !slices.Equal(full.Names, names) {
				t.Fatalf("%s: the shared schema was modified", tc.expected)
			}
			if first.Support != tc.support {
				t.Fatalf("%s: support %v err %v", tc.expected, first.Support, first.Err)
			}
			if tc.support != model.Supported {
				if !errors.Is(first.Err, tc.fail) || len(first.Samples) != 0 || !first.InvalidateSchema {
					t.Fatalf("%s: err %v, %d samples, invalidate %v", tc.expected, first.Err, len(first.Samples), first.InvalidateSchema)
				}
				return
			}
			if first.Err != nil {
				t.Fatal(first.Err)
			}
			checkRealSysfsSamples(t, tc.expected, port, first.Samples, fixture.uncataloged, unreadable, fixture.rate, nil, false)
			if want := len(full.Names) - len(unreadable); len(first.StatisticSchema.Names) != want {
				t.Fatalf("%s: pruned schema has %d names, want %d", tc.expected, len(first.StatisticSchema.Names), want)
			}
			if tc.heal {
				for _, name := range unreadable {
					rdmaWrite(t, filepath.Join(port, name), "0\n")
				}
			}
			clear(reads.count)
			job.StatisticSchema = first.StatisticSchema
			second := c.Collect(t.Context(), job)
			if second.Support != model.Supported || second.Err != nil || len(second.Samples) != len(first.Samples) {
				t.Fatalf("%s: second sample support %v err %v, %d samples, want %d", tc.expected, second.Support, second.Err, len(second.Samples), len(first.Samples))
			}
			for _, name := range unreadable {
				if n := reads.count[name]; n != 0 {
					t.Fatalf("%s: %s read %d times on the second sample", tc.expected, name, n)
				}
			}
		})
	}
}

// TestRDMARateFleet parses every rate string the fleet rescan reported.
func TestRDMARateFleet(t *testing.T) {
	for _, tc := range []struct {
		category, text string
		want           uint64
	}{
		{"positive", "400 Gb/sec (4X NDR)", 50000000000},
		{"positive", "800 Gb/sec (4X XDR)", 100000000000},
		{"positive", "400 Gb/sec (8X HDR)", 50000000000},
		{"positive", "200 Gb/sec (4X HDR)", 25000000000},
		{"positive", "200 Gb/sec (2X NDR)", 25000000000},
		{"positive", "100 Gb/sec (4X EDR)", 12500000000},
		{"positive", "100 Gb/sec (2X HDR)", 12500000000},
		{"positive", "40 Gb/sec (4X QDR)", 5000000000},
		{"positive", "25 Gb/sec (1X EDR)", 3125000000},
		{"positive", "10 Gb/sec (4X SDR)", 1250000000},
		{"positive", "10 Gb/sec (1X FDR10)", 1250000000},
		{"positive", "10 Gb/sec (1X QDR)", 1250000000},
		{"boundary", "2.5 Gb/sec (1X SDR)", 312500000},
	} {
		t.Run(tc.text, func(t *testing.T) {
			t.Logf("%s: fleet rate %q; expected: %d bytes per second", tc.category, tc.text, tc.want)
			got, err := rdmaRate(tc.text)
			if err != nil || got != tc.want {
				t.Fatalf("rdmaRate(%q) = %d, %v; want %d", tc.text, got, err, tc.want)
			}
		})
	}
}
